new Promise((resolve) => {
  const request = indexedDB.open('nook')
  request.onsuccess = () => {
    const all = request.result.transaction('docs').objectStore('docs').getAll()
    all.onsuccess = () => resolve(JSON.stringify(all.result))
  }
})

